function validate([boxes]) {
  if (!Array.isArray(boxes) || boxes.length < 1 || boxes.length > 100) return 'boxes needs 1 to 100 values.';
  if (boxes.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each colour is an integer from 1 to 100.';
  return null;
}

