function removeBoxes(boxes) {
  const n = boxes.length;
  // memo[(left * n + right) * n + extra]: best score for boxes[left..right]
  // when `extra` boxes of colour boxes[left] are already glued to its left.
  const memo = new Int32Array(n * n * n).fill(-1);

  function best(left, right, extra) {
    if (left > right) return 0;
    while (left < right && boxes[left + 1] === boxes[left]) {
      left++;
      extra++;
    }
    const key = (left * n + right) * n + extra;
    if (memo[key] >= 0) return memo[key];
    let score = (extra + 1) * (extra + 1) + best(left + 1, right, 0);
    for (let mid = left + 1; mid <= right; mid++) {
      if (boxes[mid] === boxes[left]) {
        score = Math.max(score, best(left + 1, mid - 1, 0) + best(mid, right, extra + 1));
      }
    }
    memo[key] = score;
    return score;
  }

  return best(0, n - 1, 0);
}

