function removeBoxes(boxes) {
  // A slower, mirrored formulation: bottom-up over interval length, with k boxes equal
  // to boxes[j] waiting on the right of the range, and no merging of runs.
  const n = boxes.length;
  const table = new Int32Array(n * n * (n + 1));
  const at = (i, j, k) => (i * n + j) * (n + 1) + k;
  const get = (i, j, k) => (i > j ? 0 : table[at(i, j, k)]);
  for (let len = 1; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      for (let k = 0; k <= n - 1 - j; k++) {
        let top = get(i, j - 1, 0) + (k + 1) * (k + 1);
        for (let m = i; m < j; m++) {
          if (boxes[m] === boxes[j]) top = Math.max(top, get(i, m, k + 1) + get(m + 1, j - 1, 0));
        }
        table[at(i, j, k)] = top;
      }
    }
  }
  return table[at(0, n - 1, 0)];
}

