function generate(rand, size) {
  if (size === 'large') {
    const n = 80 + Math.floor(rand() * 21);
    const shape = rand();
    if (shape < 0.15) return [Array.from({ length: n }, (_, i) => (i % 2) + 1)];
    if (shape < 0.25) return [Array.from({ length: n }, (_, i) => i + 1)];
    const colours = shape < 0.6 ? 2 + Math.floor(rand() * 3) : 2 + Math.floor(rand() * 99);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * colours))];
  }
  const n = 1 + Math.floor(rand() * 9);
  const colours = 1 + Math.floor(rand() * 4);
  const offset = rand() < 0.2 ? 96 : 0;
  return [Array.from({ length: n }, () => offset + 1 + Math.floor(rand() * colours))];
}
